#include <cstdio>
#include <vector>

std::vector<int> parent;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   // 路径压缩（隔代压缩）
        x = parent[x];
    }
    return x;
}

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    parent.resize(n + 1);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    for (int i = 0; i < q; ++i) {
        int op, a, b;
        scanf("%d %d %d", &op, &a, &b);
        int ra = find(a), rb = find(b);
        if (op == 1) {
            if (ra != rb) parent[ra] = rb;
        } else {
            printf("%s\n", ra == rb ? "YES" : "NO");
        }
    }
    return 0;
}
